const rows = $input.all();

const seen = new Map();
const result = [];

for (const item of rows) {
  const name = item.json['name'].toString().trim().toLowerCase();

  if (!name) {
    result.push(item);
    continue;
  }

  // If we've seen this email before, skip (duplicate)
  if (seen.has(name)) {
    continue;
  }

  seen.set(name, true);
  result.push(item);
}

return result;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = { ...item.json };

  const reviews = parseFloat(data['Reviews Count']) || 0;
  const rating  = parseFloat(data['Google Rating'])  || 0;

  let score;

  if (reviews >= 50 && reviews <= 800 && rating >= 3.8) {
    // Sweet spot: small-medium business, good reputation
    score = 'High';

  } else if (
    (reviews > 800) ||
    (reviews >= 20 && reviews < 50 && rating >= 3.5) ||
    (reviews >= 50 && reviews <= 800 && rating >= 3.0 && rating < 3.8)
  ) {
    // Either too big, or decent but rating slightly low
    score = 'Medium';

  } else {
    // Too few reviews, very low rating, or no data
    score = 'Low';
  }

  data["Lead's Score"] = score;
  results.push({ json: data });
}

return results;

const result = $input.item.json;
const kg = result.knowledge_graph || {};
const organicResults = result.organic_results || [];

// Extract from knowledge_graph profiles
const profiles = kg.profiles || [];
const fbProfile = profiles.find(p => p.name === "Facebook")?.link || null;
const igProfile = profiles.find(p => p.name === "Instagram")?.link || null;

// Fallback: scan organic results for Instagram/Facebook
const igOrganic = organicResults.find(r =>
  r.link?.includes("instagram.com"))?.link || null;

const fbOrganic = organicResults.find(r =>
  r.link?.includes("facebook.com"))?.link || null;

// Website: domain (between // and next /) must contain business name
const businessName = (kg.title || "")
  .toLowerCase()
  .replace(/[^a-z0-9]/g, ""); // strip spaces and special chars

const excludedDomains = [
  "tripadvisor", "timeout", "wanderlog", "yelp", "zomato",
  "happycow", "atly", "10bis", "wolt", "instagram", "facebook",
  "tiktok", "nypost", "google", "easy.co.il", "alamy"
];

const websiteOrganic = organicResults.find(r => {
  if (!r.link) return false;

  // Extract domain = part between // and next /
  const domainMatch = r.link.match(/\/\/([^\/]+)/);
  if (!domainMatch) return false;
  const domain = domainMatch[1].toLowerCase().replace(/^www\./, "");

  // Domain must contain business name
  const domainClean = domain.replace(/[^a-z0-9]/g, "");
  const nameMatches = domainClean.includes(businessName);

  // Must not be an excluded site
  const isExcluded = excludedDomains.some(d => domain.includes(d));

  return nameMatches && !isExcluded;
})?.link || null;

return {
  json: {
    business: kg.title,
    instagram: igProfile || igOrganic,
    facebook: fbProfile || fbOrganic,
    website: websiteOrganic,
  }
};

